<?php
use App\Http\Controllers\{AttendanceController,DashboardController,MemberActivityController,MemberController,PublicCheckInController};use App\Http\Controllers\Auth\AuthenticatedSessionController;use Illuminate\Support\Facades\Route;
Route::get('/health',fn()=>response()->json(['status'=>'ok','application'=>'Shepherd Church CRM']))->name('health');
Route::middleware('guest')->group(function(){Route::get('/login',[AuthenticatedSessionController::class,'create'])->name('login');Route::post('/login',[AuthenticatedSessionController::class,'store'])->middleware('throttle:6,1');});
Route::get('/check-in/{token}',[PublicCheckInController::class,'show'])->name('check-in.show');
Route::get('/check-in/{token}/members',[PublicCheckInController::class,'search'])->middleware('throttle:30,1')->name('check-in.search');
Route::post('/check-in/{token}',[PublicCheckInController::class,'checkIn'])->middleware('throttle:10,1')->name('check-in.store');
Route::post('/check-in/{token}/register',[PublicCheckInController::class,'register'])->middleware('throttle:5,1')->name('check-in.register');
Route::middleware('auth')->group(function(){Route::redirect('/','/dashboard');Route::post('/logout',[AuthenticatedSessionController::class,'destroy'])->name('logout');Route::get('/dashboard',DashboardController::class)->name('dashboard');Route::resource('members',MemberController::class);Route::post('/members/{member}/donations',[MemberActivityController::class,'donation'])->name('members.donations.store');Route::post('/members/{member}/communications',[MemberActivityController::class,'communication'])->name('members.communications.store');Route::post('/members/{member}/pastoral-notes',[MemberActivityController::class,'pastoralNote'])->name('members.pastoral-notes.store');Route::middleware('role:admin,staff,pastor')->group(function(){Route::get('/attendance',[AttendanceController::class,'index'])->name('attendance.index');Route::post('/attendance',[AttendanceController::class,'store'])->name('attendance.store');Route::patch('/attendance/{session}/status',[AttendanceController::class,'status'])->name('attendance.status');});});
